package dates

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestParseDate(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  time.Time
	}{
		{"ordinary date", "2024-03-17", time.Date(2024, time.March, 17, 0, 0, 0, 0, time.UTC)},
		{"first day of year", "2024-01-01", time.Date(2024, time.January, 1, 0, 0, 0, 0, time.UTC)},
		{"last day of year", "2024-12-31", time.Date(2024, time.December, 31, 0, 0, 0, 0, time.UTC)},
		{"leap day", "2024-02-29", time.Date(2024, time.February, 29, 0, 0, 0, 0, time.UTC)},
		{"before unix epoch", "1900-06-15", time.Date(1900, time.June, 15, 0, 0, 0, 0, time.UTC)},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseDate(tt.input)
			if err != nil {
				t.Fatalf("parseDate(%q) returned error: %v", tt.input, err)
			}
			if !got.Equal(tt.want) {
				t.Errorf("parseDate(%q) = %v, want %v", tt.input, got, tt.want)
			}
			if loc := got.Location(); loc != time.UTC {
				t.Errorf("parseDate(%q) location = %v, want UTC", tt.input, loc)
			}
			if h, m, s := got.Clock(); h != 0 || m != 0 || s != 0 || got.Nanosecond() != 0 {
				t.Errorf("parseDate(%q) clock = %02d:%02d:%02d.%09d, want midnight",
					tt.input, h, m, s, got.Nanosecond())
			}
		})
	}
}

func TestParseDateErrors(t *testing.T) {
	tests := []struct {
		name  string
		input string
	}{
		{"empty string", ""},
		{"slash separators", "2024/03/17"},
		{"unpadded month and day", "2024-3-7"},
		{"day out of range", "2024-02-30"},
		{"not a leap year", "2023-02-29"},
		{"month out of range", "2024-13-01"},
		{"trailing time component", "2024-03-17T00:00:00Z"},
		{"leading whitespace", " 2024-03-17"},
		{"not a date at all", "tomorrow"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseDate(tt.input)
			if err == nil {
				t.Fatalf("parseDate(%q) = %v, want error", tt.input, got)
			}
			if !got.IsZero() {
				t.Errorf("parseDate(%q) = %v, want zero time on error", tt.input, got)
			}
			if !strings.Contains(err.Error(), "parseDate") {
				t.Errorf("error %q does not name the function", err)
			}
			// The offending input is quoted into the message so callers can see it.
			if tt.input != "" && !strings.Contains(err.Error(), tt.input) {
				t.Errorf("error %q does not mention input %q", err, tt.input)
			}
		})
	}
}

// The error is wrapped with %w, so callers can still inspect the underlying
// *time.ParseError.
func TestParseDateWrapsParseError(t *testing.T) {
	_, err := parseDate("nope")
	if err == nil {
		t.Fatal(`parseDate("nope") = nil error, want error`)
	}

	var parseErr *time.ParseError
	if !errors.As(err, &parseErr) {
		t.Fatalf("errors.As(%v, *time.ParseError) = false, want true", err)
	}
	if parseErr.Value != "nope" {
		t.Errorf("wrapped ParseError.Value = %q, want %q", parseErr.Value, "nope")
	}
}

// parseDate must not pick up the process-local zone: a date parsed while
// time.Local is non-UTC still lands on midnight UTC.
func TestParseDateIgnoresLocalTimeZone(t *testing.T) {
	tokyo, err := time.LoadLocation("Asia/Tokyo")
	if err != nil {
		t.Skipf("tzdata unavailable: %v", err)
	}
	orig := time.Local
	time.Local = tokyo
	t.Cleanup(func() { time.Local = orig })

	got, err := parseDate("2024-03-17")
	if err != nil {
		t.Fatalf("parseDate returned error: %v", err)
	}
	want := time.Date(2024, time.March, 17, 0, 0, 0, 0, time.UTC)
	if !got.Equal(want) || got.Location() != time.UTC {
		t.Errorf("parseDate = %v (%v), want %v (UTC)", got, got.Location(), want)
	}
}

// Formatting a date and parsing it back is stable across a month boundary.
func TestParseDateRoundTrip(t *testing.T) {
	const layout = "2006-01-02"
	for d := time.Date(2024, time.February, 25, 0, 0, 0, 0, time.UTC); d.Month() != time.March || d.Day() <= 5; d = d.AddDate(0, 0, 1) {
		s := d.Format(layout)
		got, err := parseDate(s)
		if err != nil {
			t.Fatalf("parseDate(%q) returned error: %v", s, err)
		}
		if got.Format(layout) != s {
			t.Errorf("parseDate(%q) round-tripped to %q", s, got.Format(layout))
		}
	}
}
```

A few notes on the coverage choices:

- **`got.Equal(tt.want)` plus an explicit `Location()` check.** `Equal` compares instants, not wall-clock representations, so it would pass for an identical instant in a different zone — the separate location assertion is what actually pins the `.UTC()` call.
- **`time.Local` swap.** With the layout `"2006-01-02"` (no zone element) `time.Parse` already returns UTC, so the `.UTC()` in `parseDate` is a no-op today. That test locks in the guarantee against someone switching to `time.ParseInLocation` or adding a zone token later.
- **Error cases assert the zero time**, since `parseDate` returns `time.Time{}` rather than the partially-parsed value.
- **`errors.As`** is what verifies the `%w` verb rather than `%v`.
- The empty-input case skips the "message mentions the input" assertion, because `strings.Contains(s, "")` is trivially true.

